"""Generate per-quark JSON datasheets under ``AutoGenerated/quarks/``.

Iterates :data:`metaphysica.datasheets.quark.KNOWN_QUARKS` (12 entries:
6 quarks + 6 antiquarks), calls
:func:`metaphysica.datasheets.quark.build_quark_datasheet` for each,
and writes one canonical ``<CamelName>.json`` file per entry into
``<out_dir>/AutoGenerated/quarks/``.

The output directory is resolved via
:func:`metaphysica.generators._common.autogen_dir`, so this script
honours the ``METAPHYSICA_OUT`` env var set by
:mod:`metaphysica.build`.

This is a smaller, more focused companion to
:mod:`metaphysica.generators.generate_datasheets`, which writes into
the wheel data tree plus an ``AutoGenerated/datasheets/`` mirror. The
generator here exists to populate the legacy
``AutoGenerated/quarks/`` path expected by the static site templates.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import List, Tuple

from metaphysica.generators._common import autogen_dir


def _camel_filename(name: str) -> str:
    """Turn a quark display name into a canonical CamelCase filename.

    "Up Quark"        -> "UpQuark.json"
    "Antiup Quark"    -> "AntiupQuark.json"
    "Strange Quark"   -> "StrangeQuark.json"
    """
    return name.replace(" ", "") + ".json"


def _write_json(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(payload, indent=2, ensure_ascii=False, default=str),
        encoding="utf-8",
    )


def generate() -> Tuple[int, List[str]]:
    """Build a datasheet for every known quark and write into AutoGenerated/quarks/.

    Returns ``(n_written, failures)``.
    """
    from metaphysica.datasheets.quark import (
        KNOWN_QUARKS, build_quark_datasheet,
    )

    out_dir = autogen_dir() / "quarks"
    out_dir.mkdir(parents=True, exist_ok=True)

    written = 0
    failures: List[str] = []
    for canonical in KNOWN_QUARKS:
        try:
            # prefer_bundled=True is fine: the wheel snapshot was generated
            # by build_quark_datasheet(prefer_bundled=False) at release time,
            # so it's the same content but cheaper to load.
            payload = build_quark_datasheet(canonical, prefer_bundled=True)
        except Exception as exc:
            failures.append(
                f"{canonical}: {type(exc).__name__}: {exc}"
            )
            continue

        display_name = payload.get("Name") or canonical
        slug = _camel_filename(display_name)
        _write_json(out_dir / slug, payload)
        written += 1

    return written, failures


def main() -> int:
    print("=== Generate AutoGenerated/quarks/ datasheets ===")
    n, failures = generate()
    print(f"Wrote {n} quark datasheet(s) into AutoGenerated/quarks/.")
    if failures:
        print(f"Failures ({len(failures)}):")
        for f in failures:
            print(f"  {f}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
